// Package nasm compiles a verified METALS module to x86-64 NASM
// assembly for Linux, following the layout and ABI in docs/appendix-e-native-backend.md.
// The generated file links against the embedded C runtime (rt.c).
package nasm

import (
	"fmt"
	"sort"
	"strconv"
	"strings"

	"github.com/gyro-lang/gyro/internal/metals"
)

// Generate compiles the module to one NASM source file.
func Generate(module *metals.Module) (asm string, err error) {
	registerTypes, err := metals.RegisterTypes(module)
	if err != nil {
		return "", fmt.Errorf("nasm: %w", err)
	}

	g := &generator{
		module:         module,
		regTypes:       registerTypes,
		types:          map[string]*metals.TypeDecl{},
		imports:        map[string]*metals.FnType{},
		funcs:          map[string]*metals.Func{},
		symbols:        map[string]string{},
		usedSyms:       map[string]bool{},
		externs:        map[string]bool{},
		externSyms:     map[string]bool{},
		strLits:        map[string]string{},
		cstrs:          map[string]string{},
		anyTypes:       map[string]string{},
		buildingAny:    map[string]bool{},
		eqHelpers:      map[string]string{},
		thunks:         map[string]string{},
		indirectThunks: map[string]string{},
		globals:        map[string]*metals.Global{},
		globalSyms:     map[string]string{},
		memories:       map[string]*metals.Memory{},
		memorySyms:     map[string]string{},
	}
	for _, global := range module.Globals {
		g.globals[global.Name] = global
	}
	for _, mem := range module.Memories {
		g.memories[mem.Name] = mem
	}
	for _, decl := range module.Types {
		g.types[decl.Name] = decl
	}
	g.layout = metals.NewLayout(module, failf)
	for _, imp := range module.Imports {
		library := metals.ExternLibrary(imp.Module)
		for _, fn := range imp.Funcs {
			g.imports[fn.Name] = fn.Sig
			if library != "" {
				g.externSyms[fn.Name] = true
			}
		}
	}
	for _, fn := range module.Funcs {
		g.funcs[fn.Name] = fn
	}

	defer func() {
		if failure := recover(); failure != nil {
			genErr, ok := failure.(*genError)
			if !ok {
				panic(failure)
			}
			err = genErr.err
		}
	}()

	if g.funcs["main"] == nil {
		g.fail("the module has no main")
	}

	for _, fn := range module.Funcs {
		g.genFunc(fn)
	}
	g.drainPending()
	return g.assemble(), nil
}

type generator struct {
	// at is the source position the line table currently credits.
	at       metals.Loc
	module   *metals.Module
	regTypes map[string]map[string]metals.Type
	types    map[string]*metals.TypeDecl
	// layout answers every size, alignment and offset question, so that
	// the two backends cannot pad a struct differently.
	layout  *metals.Layout
	imports map[string]*metals.FnType
	funcs   map[string]*metals.Func
	// externSyms holds the imports that name a C library's symbol rather
	// than the runtime's, which are called through a generated wrapper.
	externSyms map[string]bool

	text strings.Builder
	// data is .rodata, which is what a constant the program only reads
	// wants; rwdata is .data, for a global that starts as bytes and may
	// be written; bss is the zeroed storage that costs no object bytes.
	data   strings.Builder
	rwdata strings.Builder
	bss    strings.Builder

	globals    map[string]*metals.Global
	globalSyms map[string]string
	memories   map[string]*metals.Memory
	memorySyms map[string]string

	symbols  map[string]string // METALS function name -> asm symbol
	usedSyms map[string]bool
	externs  map[string]bool
	strLits  map[string]string // decoded literal -> data label
	cstrs    map[string]string // NUL-terminated C string -> data label

	// anyTypes interns one descriptor per type the program wraps or
	// tests, so that identity is structural equality.
	anyTypes    map[string]string
	buildingAny map[string]bool
	anyN        int
	floatN      int
	labelN      int

	eqHelpers map[string]string // type string -> helper symbol
	thunks    map[string]string // async callee -> thunk symbol
	// indirectThunks keys on the signature instead: a call through a
	// function value has no callee symbol to name.
	indirectThunks map[string]string
	pending        []func() // helpers and thunks queued during emission
}

type genError struct{ err error }

func (g *generator) fail(format string, args ...any) {
	failf(format, args...)
}

// failf aborts code generation from anywhere, including the value
// helpers that have no generator to hand. Generate recovers it.
func failf(format string, args ...any) {
	panic(&genError{fmt.Errorf("nasm: "+format, args...)})
}

// drainPending emits queued helper functions; emitting one may queue
// more, so the loop runs until the list is empty.
func (g *generator) drainPending() {
	for len(g.pending) > 0 {
		next := g.pending[0]
		g.pending = g.pending[1:]
		next()
	}
}

func (g *generator) assemble() string {
	var out strings.Builder
	out.WriteString("; generated by gyro build — see docs/appendix-e-native-backend.md\n")
	out.WriteString("default rel\n")
	out.WriteString("global gy_user_main\n")

	externs := make([]string, 0, len(g.externs))
	for name := range g.externs {
		externs = append(externs, name)
	}
	sort.Strings(externs)
	for _, name := range externs {
		out.WriteString("extern " + name + "\n")
	}

	out.WriteString("\nsection .text\n")
	out.WriteString(g.text.String())
	if g.at != (metals.Loc{}) {
		// NASM mis-encodes the line table's last advance when the final
		// row sits between 128 and 255 bytes from the end of the section,
		// which truncates the table and loses every row after it. A row
		// one byte from the end makes that advance one byte.
		out.WriteString("%line 1+0 \"gyro:end\"\n\tint3\n")
	}
	out.WriteString("\nsection .rodata\n")
	out.WriteString(g.data.String())
	if g.rwdata.Len() > 0 {
		out.WriteString("\nsection .data\n")
		out.WriteString(g.rwdata.String())
	}
	if g.bss.Len() > 0 {
		out.WriteString("\nsection .bss\n")
		out.WriteString(g.bss.String())
	}
	return out.String()
}

// globalSymbol names module storage, reserving its bytes on first use.
// Zeroed storage belongs in .bss and costs nothing in the object file; a
// global that carries a static image is real bytes in .data, which is
// writable because a global is.
func (g *generator) globalSymbol(name string) string {
	if symbol, ok := g.globalSyms[name]; ok {
		return symbol
	}
	global, ok := g.globals[name]
	if !ok {
		g.fail("no global @%s", name)
	}
	symbol := uniqueSymbol("G_"+sanitize(name), g.usedSyms)
	g.usedSyms[symbol] = true
	g.globalSyms[name] = symbol

	// Aligned to a word, which is the most any type asks for: a global
	// whose size is not a multiple of one would otherwise leave the next
	// one wherever it fell.
	if global.Bytes != nil {
		g.rwdata.WriteString("\talign 8\n")
		g.rwdata.WriteString(symbol + ":\n")
		writeBytes(&g.rwdata, global.Bytes)
		return symbol
	}
	g.bss.WriteString("\talign 8\n")
	g.bss.WriteString(symbol + ":\n")
	fmt.Fprintf(&g.bss, "\tresb %d\n", g.sizeOf(global.Type))
	return symbol
}

// writeBytes emits a byte image as db lines, wrapped so a long one stays
// readable in the generated assembly.
func writeBytes(out *strings.Builder, bytes []byte) {
	const perLine = 16
	for at := 0; at < len(bytes); at += perLine {
		end := min(at+perLine, len(bytes))
		out.WriteString("\tdb ")
		for i, b := range bytes[at:end] {
			if i > 0 {
				out.WriteString(", ")
			}
			fmt.Fprintf(out, "%d", b)
		}
		out.WriteString("\n")
	}
}

// ---------------------------------------------------------------------------
// Emission primitives
// ---------------------------------------------------------------------------

func (g *generator) ins(format string, args ...any) {
	g.text.WriteString("\t")
	fmt.Fprintf(&g.text, format, args...)
	g.text.WriteString("\n")
}

// mark points the line table at a source line. NASM's %line sets the line
// the following assembly lines are credited to, and +0 keeps it there
// instead of counting up. A repeat of the position in force is not
// written, so a statement that lowers to several Locs costs one.
func (g *generator) mark(loc *metals.Loc) {
	if g.at == *loc {
		return
	}
	g.at = *loc
	fmt.Fprintf(&g.text, "%%line %d+0 %s\n", loc.Line, strconv.Quote(loc.File))
}

func (g *generator) label(name string) {
	g.text.WriteString(name + ":\n")
}

func (g *generator) comment(format string, args ...any) {
	g.text.WriteString("\t; ")
	fmt.Fprintf(&g.text, format, args...)
	g.text.WriteString("\n")
}

func (g *generator) newLabel() string {
	g.labelN++
	return fmt.Sprintf(".L%d", g.labelN)
}

func (g *generator) extern(symbol string) string {
	g.externs[symbol] = true
	return symbol
}

// ---------------------------------------------------------------------------
// Symbols and data
// ---------------------------------------------------------------------------

// symbolFor maps a METALS function name to a unique asm symbol. main
// becomes gy_user_main, the entry point the C runtime calls.
func (g *generator) symbolFor(name string) string {
	if symbol, ok := g.symbols[name]; ok {
		return symbol
	}
	symbol := "gy_user_main"
	if name != "main" {
		symbol = uniqueSymbol("F_"+sanitize(name), g.usedSyms)
	}
	g.usedSyms[symbol] = true
	g.symbols[name] = symbol
	return symbol
}

func sanitize(name string) string {
	var out strings.Builder
	for _, ch := range name {
		if ch >= 'a' && ch <= 'z' || ch >= 'A' && ch <= 'Z' || ch >= '0' && ch <= '9' || ch == '_' {
			out.WriteRune(ch)
		} else {
			out.WriteByte('_')
		}
	}
	return out.String()
}

func uniqueSymbol(base string, used map[string]bool) string {
	if !used[base] {
		return base
	}
	for i := 2; ; i++ {
		candidate := base + "_" + strconv.Itoa(i)
		if !used[candidate] {
			return candidate
		}
	}
}

// strLabel interns a string literal: a { len, bytes } header in rodata.
func (g *generator) strLabel(text string) string {
	if label, ok := g.strLits[text]; ok {
		return label
	}
	label := fmt.Sprintf("S_%d", len(g.strLits))
	g.strLits[text] = label

	g.data.WriteString(label + ":\n")
	fmt.Fprintf(&g.data, "\tdq %d ; %s\n", len(text), strconv.Quote(clipComment(text)))
	if len(text) == 0 {
		return label
	}
	g.data.WriteString("\tdb ")
	for i := 0; i < len(text); i++ {
		if i > 0 {
			g.data.WriteString(", ")
		}
		fmt.Fprintf(&g.data, "%d", text[i])
	}
	g.data.WriteString("\n")
	return label
}

func clipComment(text string) string {
	text = strings.ReplaceAll(text, "\n", " ")
	if len(text) > 40 {
		return text[:40] + "..."
	}
	return text
}
